/* 03: fewer actions, income-to-month-end cash flow; native collection stays explicitly unimplemented. */
const covers={mountains:{src:'assets/mountains.jpg',name:'山海',icon:'mountain'},headphones:{src:'assets/headphones.jpg',name:'好物',icon:'headphone'},home:{src:'assets/home.jpg',name:'生活',icon:'house'},journey:{src:'assets/journey.jpg',name:'远行',icon:'plane'}};
const sourceColors=['#2684ec','#28a475','#bd8d5f','#8b71cf','#da7d86'];
const themes=[{id:'frost',name:'晴空白',caption:'清透 · 蓝色',colors:['#f2f4f8','#087efa','#d6eaff']},{id:'cream',name:'奶油纸',caption:'暖白 · 陶土',colors:['#f4efe7','#a26946','#e9d4b9']},{id:'forest',name:'雾松绿',caption:'薄雾 · 森林',colors:['#eef3ef','#347461','#b5cfc0']},{id:'night',name:'午夜黑',caption:'深色 · 冰蓝',colors:['#121418','#71b3ff','#303d51']}];
function initializeV3(){const s=state();if(!s.v3){s.v3={theme:s.dark?'night':'frost',sources:[{id:'alipay',name:'支付宝',kind:'cash'},{id:'wechat',name:'微信',kind:'cash'},{id:'bank',name:'银行卡',kind:'cash'},{id:'huabei',name:'花呗',kind:'credit'},{id:'baitiao',name:'京东白条',kind:'credit'}],cash:{opening:0,incomes:[{id:'salary-'+M.month(),name:'工资',amount:s.work.salary,date:M.dueDate(M.month(),5),received:Number(M.today().slice(8))>=5}],fixed:[],anchor:null}};}s.v3.sources??=[];s.v3.cash.fixed??=[];s.v3.cash.incomes??=[];for(const w of s.wishes)w.cover??=w.icon==='headphone'?'headphones':w.icon==='plane'?'journey':'home';for(const g of s.goals)g.cover??='mountains';}
initializeV3();
const oldReset=M.reset;M.reset=()=>{oldReset();initializeV3();return state();};
const v3=()=>state().v3;
const total=(items,fn=x=>x.amount)=>M.round(items.reduce((s,x)=>s+fn(x),0));
const isCredit=t=>!!t.credit||v3().sources.some(s=>s.kind==='credit'&&s.name===t.account);
const expenseSign=t=>t.type==='refund'?-1:t.type==='expense'?1:0;
M.spending=(month=M.month(),category)=>total(M.monthlyTx(month).filter(t=>!category||t.category===category),t=>expenseSign(t)*t.amount);
function cashSummary(){const m=M.month(),today=M.today(),day=Number(today.slice(8)),monthDays=Number(M.dueDate(m,31).slice(8)),left=monthDays-day,tx=M.monthlyTx(),incomeRows=v3().cash.incomes.filter(t=>t.date.startsWith(m)),received=total(incomeRows.filter(t=>t.received&&t.date<=today))+total(tx.filter(t=>t.type==='income'&&t.date<=today)),cashSpent=total(tx.filter(t=>!isCredit(t)&&t.date<=today),t=>expenseSign(t)*t.amount),paid=total(state().debts.flatMap(d=>d.schedule).filter(p=>p.paid&&(p.paidDate||p.date).startsWith(m)),p=>p.total),allocated=M.goalAllocation(),derived=M.round(v3().cash.opening+received-cashSpent-paid-allocated),anchor=v3().cash.anchor?.month===m?v3().cash.anchor:null,now=M.round(anchor?anchor.amount+derived-anchor.baseline:derived),fixed=v3().cash.fixed.filter(f=>!tx.some(t=>t.type==='expense'&&t.name.includes(f.name)&&t.date.startsWith(m))),futureFixed=total(fixed),variable=tx.filter(t=>['expense','refund'].includes(t.type)&&!isCredit(t)&&t.date<=today&&!/房租|房贷|水电|保险|年费/.test(t.name)&&!v3().cash.fixed.some(f=>t.name.includes(f.name))),observed=Math.max(0,total(variable,t=>expenseSign(t)*t.amount)),daily=observed/Math.max(1,day),futureDaily=M.round(daily*left),unpaid=M.due(m,true),expected=total(incomeRows.filter(t=>!t.received&&t.date>=today)),forecast=M.round(now+expected-futureFixed-unpaid-futureDaily),spread=M.round(futureDaily*.3);return {received,cashSpent,paid,allocated,now,forecast,expected,futureFixed,futureDaily,unpaid,daily,left,derived,low:M.round(forecast-spread),high:M.round(forecast+spread),sample:variable.length,monthDays};}
M.available=()=>cashSummary().forecast;
const rawDuplicate=M.duplicate;M.duplicate=t=>rawDuplicate(t)||(t.type==='income'&&/工资|薪资/.test(t.name)&&v3().cash.incomes.some(i=>i.received&&i.date.slice(0,7)===t.date.slice(0,7)&&i.amount===t.amount));
const coverSrc=x=>typeof x.cover==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(x.cover)?x.cover:(covers[x.cover]?.src||covers[x.icon==='headphone'?'headphones':'mountains'].src);
const coverImg=(x,cls='')=>`<img class="${cls}" src="${h(coverSrc(x))}" alt="${h(x.name)}" loading="lazy">`;
function applyTheme(){const theme=themes.some(t=>t.id===v3().theme)?v3().theme:'frost';document.body.dataset.theme=theme;$('#app-shell').dataset.theme=theme;}
const baseRender=render;render=function(keep=true){initializeV3();applyTheme();baseRender(keep);};
navs.splice(0,navs.length,['home','余钱','wallet'],['ledger','收支','book'],['plan','期待','mountain'],['profile','设置','user']);planTab='wishes';
header=function(title,tools=''){return `<header class="page-header"><div class="eyeline"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span class="demo-dot">网页体验 03</span></div><div class="title-line"><h1>${title}</h1><div class="toolbar">${tools}</div></div></header>`;};
transaction=function(t){const income=t.type==='income',refund=t.type==='refund',transfer=t.type==='transfer';return action(t._cashIncome?'v3-income':'transaction',`<span class="tx-icon ${income||refund?'mint':''}">${icon(income?'wallet':refund?'reset':transfer?'arrow':t.icon||'bag')}</span><span class="flex-copy"><strong>${h(t.name)}</strong><small>${h(t.account)} · ${income?'收入':refund?'退款':transfer?'账户间转账':isCredit(t)?'赊购 · 还款时计现金支出':h(t.category)}</small></span><span class="tx-value ${income||refund?'positive':''}"><strong>${income||refund?'+':transfer?'':'−'}${yuan(t.amount)}</strong><small>${income?'已到账':refund?'退回':transfer?'不重复计支出':duration(t.amount)+'工作'}</small></span>`,'transaction',`data-id="${h(t.id)}"`);};
home=function(){const c=cashSummary(),salary=v3().cash.incomes.find(i=>i.id==='salary-'+M.month()),first=M.installments().filter(p=>!p.paid).sort((a,b)=>a.date.localeCompare(b.date))[0];return header('余钱',action('v3-themes','<span class="theme-dot"></span>','round-button','aria-label="切换主题皮肤"'))+
`<section class="cash-hero"><div class="forecast-label"><span>月底预计还能剩</span>${action('v3-forecast','怎么算的 '+icon('info'),'forecast-info')}</div><div class="forecast-number"><span>${c.forecast<0?'−¥':'¥'}</span>${money(Math.abs(c.forecast))}</div><div class="forecast-range">参考范围 ${yuan(c.low)} — ${yuan(c.high)}</div><div class="cash-spark"><svg viewBox="0 0 330 76" aria-label="余钱预测示意曲线"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".13"/><stop offset="100%" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><path d="M3 14C32 13 48 20 75 20S121 33 151 34S190 38 217 43L327 63V75H3Z" fill="url(#fade)"/><path d="M3 14C32 13 48 20 75 20S121 33 151 34S190 38 217 43" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="M217 43Q275 52 327 63" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="4 6"/><circle cx="217" cy="43" r="4" fill="currentColor"/></svg><div><span>${mLabel(M.month())}1日</span><span>今天</span><span>月底</span></div></div><div class="cash-hero-footer"><span>${c.sample<10?'样本较少 · 仅按已收录数据估算':'按已收录数据估算'} · 非实时余额</span>${action('v3-balance','校准余额','link')}</div></section>
<div class="cash-metrics">${action('v3-income',`<span>工资 / 收入到账</span><strong>${yuan(c.received)}</strong><small>${salary?.received?'已收录 · 点此修改':'点一下确认工资到账'} ${chevron()}</small>`,'card')}${action('v3-repayments',`<span>接下来要还</span><strong>${yuan(c.unpaid)}</strong><small>${first?`${dateLabel(first.date)} · ${h(first.name)}`:'本月没有待还'} ${chevron()}</small>`,'card')}</div>
<div class="one-touch-actions">${action('calculator',icon('calc')+'买它要工作多久','primary')}</div>
${action('v3-collection',`<span class="capture-mark">${icon('shield')}</span><span><strong>让记录少打扰你</strong><small>网页支持账单文件 / 文字；安卓自动收录待开发</small></span>${chevron()}`,'capture-banner')}
${section('接下来','v3-quick-debt','加一笔应还')}${first?group(M.installments().filter(p=>!p.paid).slice(0,2).map(p=>row(h(p.name),`${p.date.slice(5)} · ${yuan(p.total)}`,'debt',`data-id="${h(p.debtId)}"`,'plan')).join('')):action('v3-quick-debt','没有待还，或直接粘贴一条还款提醒','empty-card')}
${state().goals[0]?section('正在攒的期待','go-goals','看全部')+goalCard(state().goals[0]):''}<p class="home-prototype-note">初始为演示数据；漏记会影响预测。${action('v3-forecast','查看依据','link')}</p>`;};
ledger=function(){const c=cashSummary(),records=[...M.monthlyTx(),...v3().cash.incomes.filter(i=>i.received&&i.date.startsWith(M.month())).map(i=>({...i,type:'income',account:'到账记录',_cashIncome:true}))].filter(t=>(ledgerFilter==='全部'||(ledgerFilter==='收入'?t.type==='income':ledgerFilter==='退款'?t.type==='refund':ledgerFilter==='支出'?t.type==='expense':true))&&(ledgerAccount==='全部'||t.account===ledgerAccount)&&t.name.toLowerCase().includes(ledgerSearch.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)),dates=[...new Set(records.map(t=>t.date))];return header('收支',iconButton('v3-collection','upload','收录账单'))+`<div class="cashflow-summary card"><div><span>本月已到账</span><strong>${yuan(c.received)}</strong></div><div><span>已经付出去</span><strong>${yuan(c.cashSpent+c.paid)}</strong></div><div class="cashflow-net"><span>本月收支结余</span><strong>${yuan(c.received-c.cashSpent-c.paid)}</strong></div></div>${action('v3-collection',icon('upload')+'导入一份完整账单，补齐历史','import-history')}${note('不要求每天记账。这里用来回看、补历史和处理例外。')}
<div class="search-box">${icon('search')}<input type="search" id="ledger-search" placeholder="找一笔收支" value="${h(ledgerSearch)}" aria-label="搜索收支">${action('ledger-account',h(ledgerAccount)+icon('down'),'account-filter')}</div><div class="chips">${['全部','支出','收入','退款'].map(c=>pill(c,ledgerFilter===c,`data-filter="${c}"`)).join('')}</div>${dates.map(d=>`<div class="date-heading">${dateLabel(d)}<span>${records.filter(t=>t.date===d).length} 笔</span></div>${group(records.filter(t=>t.date===d).map(transaction).join(''))}`).join('')||empty('还没有收支记录','导入账单文件，或粘贴一段支付提醒。','v3-collection','收录账单')}${section('其他操作')}${group(row('补一笔遗漏','可选，不必每天做','new-transaction','','edit')+row('固定账单','只在需要时添加','v3-fixed','','plan'))}`;};
goalCard=function(g){const b=M.balance(g),pct=Math.min(100,Math.max(0,b/g.target*100));return action('goal',`<div class="saving-cover">${coverImg(g)}<span class="saving-tag">${icon('wallet')}正在攒</span><strong>${h(g.name)}</strong></div><div class="saving-body"><div><span>已存 ${yuan(b)} <small>/ ${yuan(g.target)}</small></span><strong>${money(pct)}<small>%</small></strong></div><div class="progress"><i style="width:${pct}%"></i></div><p>还差 ${yuan(Math.max(0,g.target-b))}<span>存一笔 ${chevron()}</span></p></div>`,'card visual-goal',`data-id="${h(g.id)}"`);};
plan=function(){const goals=planTab==='goals';return header('期待',iconButton(goals?'v3-new-goal':'v3-new-wish','plus',goals?'建立存钱目标':'收藏心愿'))+`<div class="expect-tabs">${[['wishes','先收藏',state().wishes.length],['goals','已经在攒',state().goals.length]].map(([key,name,count])=>`<button data-plan="${key}" class="${planTab===key?'active':''}">${name}<span>${count}</span></button>`).join('')}</div>`+(goals?`${note('已经决定开始存钱的期待。只记存入进度，不要求每月固定存。')}${state().goals.map(goalCard).join('')||empty('还没有开始攒的目标','从收藏里选一个，一键开始。','v3-new-goal','新建目标')}`:`${note('先留住喜欢的。价格与时间成本帮你决定，收藏不代表要购买。')}<div class="wish-grid">${state().wishes.map(w=>action('wish',`<div>${coverImg(w)}<span class="wish-photo-icon">${icon(w.icon||'bag')}</span></div><section><h3>${h(w.name)}</h3><strong>${yuan(w.price)}</strong><p>${duration(w.price)}工作</p></section>`,'photo-wish',`data-id="${h(w.id)}"`)).join('')}</div>${action('v3-new-wish','＋ 收藏一个心愿','add-line')}`);};
profile=function(){return header('设置')+`${section('外观')}${action('v3-themes',`<span class="theme-preview-mini"><i></i><b></b><em></em></span><span class="flex-copy"><strong>${themes.find(t=>t.id===v3().theme)?.name||'晴空白'}</strong><small>主题、配色与深色外观</small></span>${chevron()}`,'theme-setting card')}${section('只设置有用的')}${group(row('工资与工时',`时薪 ${yuan(M.rate())}`,'rate','','clock')+row('工资到账记录',`${yuan(cashSummary().received)}`,'v3-income','','wallet')+row('来源与收录方式',`${v3().sources.length} 个来源`,'v3-collection','','upload')+row('固定支出','可选','v3-fixed','','plan'))}${section('本机数据')}${group(row('导出数据备份','保存一份','export','','shield')+row('恢复备份','选择文件','restore','','reset')+row('版本与参考','体验版 03','about','','info')+row('重置体验','','reset','','reset'))}${note('修改只保存在当前浏览器；换设备前可导出备份。')}`;};
const rawSave=M.save;M.save=()=>{for(const t of state().transactions){if(t.account&&!v3().sources.some(s=>s.name===t.account))v3().sources.push({id:M.uid(),name:t.account,kind:/信用卡|花呗|白条|借款/.test(t.account)?'credit':'cash'});}return rawSave();};
const baseGoalView=goalView;goalView=function(r){const result=baseGoalView(r),g=state().goals.find(g=>g.id===r.id);return g?result.replace('<div class="goal-detail">',`<div class="goal-photo-detail">${coverImg(g)}</div><div class="goal-detail">`).replace('调整目标</span>','调整目标与封面</span>').replace('data-action="edit-goal"','data-action="v3-edit-goal"').replace(/<div class="plain-row"><span>计划每月存入<\/span><strong>.*?<\/strong><\/div>/,''):result;};
wishView=function(r){const w=state().wishes.find(x=>x.id===r.id);if(!w)return sheetChrome('心愿',note('已移除'));return sheetChrome('先收藏',`<div class="wish-detail-photo">${coverImg(w)}<span>${icon(w.icon||'bag')}</span></div><div class="wish-detail-copy"><h2>${h(w.name)}</h2><strong>${yuan(w.price)}</strong><p>${duration(w.price)}工作收入</p>${w.note?`<small>${h(w.note)}</small>`:''}</div>${action('v3-start-saving','开始为它攒钱','primary full',`data-id="${h(w.id)}"`)}${action('wish-calc','看看分期成本','secondary full',`data-id="${h(w.id)}"`)}${group(row('改名称、价格或封面','','v3-edit-wish',`data-id="${h(w.id)}"`))}${action('delete-wish','移除收藏','danger full',`data-id="${h(w.id)}"`)}`);};
rateView=function(){return sheetChrome('工资换成时间',`<div class="rate-hero"><span>你的到手时薪</span><strong>${yuan(M.rate('work'))}<small>/ 小时</small></strong></div>${group(row('到手月工资',yuan(state().work.salary),'work-field','data-key="salary"')+row('每月工作',`${state().work.days} 天`,'work-field','data-key="days"')+row('每天工作',`${state().work.hours} 小时`,'work-field','data-key="hours"'))}${note('例如：月薪 10,000 元 ÷ 22 天 ÷ 8 小时 = 每小时 56.82 元。这个数字用于“买它要工作多久”。')}<details class="optional-settings"><summary>可选：把通勤也看作工作投入 ${icon('down')}</summary><p>每天工作 8 小时、来回通勤 1 小时，就是为这份工作投入 9 小时。收入不变，折算后的时薪会降低。</p>${group(`<button class="list-row" data-action="v3-basis" role="switch" aria-checked="${state().work.basis==='real'}"><span class="row-label">消费换算包含通勤与额外成本</span><span class="switch ${state().work.basis==='real'?'on':''}"></span></button>`+row('往返通勤',`${state().work.commuteMinutes} 分钟`,'work-field','data-key="commuteMinutes"')+row('额外工作成本',yuan(state().work.workCost),'work-field','data-key="workCost"'))}<p>此口径时薪 ${yuan(M.rate('real'))} / 小时。当前使用${state().work.basis==='real'?'此口径':'仅工作时间'}。</p></details>`);};
const baseCalcResults=calcResults;
calculatorView=function(r){const d=r.draft;return sheetChrome('买它要工作多久',`<input class="inline-name" id="quick-product" value="${h(d.name)}" placeholder="想买什么（可不填）" aria-label="商品名称"><div class="price-entry"><label for="calc-price">商品价格</label><div><span>¥</span><input id="calc-price" type="number" inputmode="decimal" min=".01" max="9999999" step=".01" value="${d.price}" aria-label="商品价格"></div></div><div class="term-options">${[1,3,6,12].map(n=>pill(n===1?'一次付清':`${n}期`,d.terms===n,`data-terms="${n}"`)).join('')}</div>${d.terms>1?`<div class="inline-fees"><label>费用方式<select id="quick-fee-mode"><option value="zero" ${d.mode==='zero'?'selected':''}>免息</option><option value="flat" ${d.mode==='flat'?'selected':''}>每期固定费率</option><option value="apr" ${d.mode==='apr'?'selected':''}>年利率 / 等额本息</option></select></label>${d.mode!=='zero'?`<label>${d.mode==='apr'?'年利率':'每期费率'}<span><input id="quick-fee-rate" type="number" inputmode="decimal" min="0" max="100" step=".01" value="${d.rate}" aria-label="费率">%</span></label>`:''}</div><details class="optional-settings"><summary>首期费用、其他期数与还款日 ${icon('down')}</summary><div class="inline-fees"><label>首期手续费<input id="quick-fee-upfront" type="number" inputmode="decimal" min="0" max="999999" value="${d.upfront}" aria-label="首期手续费"></label><label>期数<input id="quick-fee-terms" type="number" min="2" max="60" value="${d.terms}" aria-label="期数"></label><label>还款日<input id="quick-fee-day" type="number" min="1" max="31" value="${d.day}" aria-label="还款日"></label></div></details>`:''}<div id="calc-results">${baseCalcResults(d)}</div>${action('v3-save-calculation',d.terms>1?'直接加入应还':'收藏这个心愿','primary full')}${d.terms>1?action('v3-save-calc-wish','先收藏，再想想','text-button full'):''}${note('所有费率都是示例，可直接改。应还按本金与息费合计，未连接实际借款平台。')}`);};
function forecastView(){const c=cashSummary();return sheetChrome('月底余钱怎么算',`<div class="detail-hero"><span>按当前已收录数据，预计月底可用</span><strong>${yuan(c.forecast)}</strong></div>${group([['当前可用（记录估算）',c.now],['尚未到账的预期收入',c.expected],['未付的固定账单',-c.futureFixed],['未还的分期',-c.unpaid],[`剩余 ${c.left} 天的日常支出估计`,-c.futureDaily]].map(([title,n])=>`<div class="plain-row"><span>${title}</span><strong>${n<0?'−':''}${yuan(Math.abs(n))}</strong></div>`).join(''))}${note(`没有使用分类预算。日常支出按本月已记录的非固定现金支出 ÷ 已过天数估算；当前样本 ${c.sample} 笔。退款抵扣支出，赊购在还款时扣现金，目标存入作为预留。`)}${note('曲线是示意图；参考范围只对未来日常支出做 ±30% 情景变化，不是统计置信区间。通知或账单缺漏、现金消费与未来变化都会影响结果。')}${action('v3-balance','只校准一次当前可用余额','secondary full')}${action('v3-fixed','补充房租等固定账单','text-button full')}`);}
function incomeView(r){const income=r.other&&!r.id?null:r.id?v3().cash.incomes.find(x=>x.id===r.id):v3().cash.incomes.find(x=>x.id==='salary-'+M.month());return sheetChrome(r.other?'还有一笔收入':'工资到账了',`<div class="income-illustration">${icon('wallet')}<span>${income?.received?'这笔工资已收录，修改不会重复添加':'确认金额就好，工时沿用已有设置'}</span></div><div class="price-entry"><label for="income-amount">${r.other?'这次到账':'到手工资'}</label><div><span>¥</span><input id="income-amount" type="number" inputmode="decimal" min=".01" max="9999999" value="${r.other?'':income?.amount||state().work.salary}" placeholder="0.00" aria-label="到账金额"></div></div><details class="optional-settings"><summary>修改日期或补充其他信息 ${icon('down')}</summary><label class="compact-input">到账日期<input id="income-date" type="date" value="${(income?.received?income.date:M.today())}"></label>${r.other?'<label class="compact-input">收入名称<input id="income-name" value="其他收入" maxlength="40"></label>':''}<label class="compact-input">本月开始时可用的钱（选填）<input id="income-opening" type="number" inputmode="decimal" value="${v3().cash.opening}" min="-9999999" max="9999999"></label></details>${action('v3-save-income',income?.received?'保存这笔到账':'到账了','primary full')}${!r.other?action('v3-other-income','还有一笔其他收入','text-button full'):''}${note('只记录到账，不操作银行账户。月底余额预测会同步变化。')}`);}
function balanceView(){const c=cashSummary();return sheetChrome('校准可用余额',`<p class="sheet-subtitle">如果历史记录不完整，直接用你现在可花的钱作为起点。</p><div class="price-entry"><label for="balance-amount">截至今天，可用余额</label><div><span>¥</span><input id="balance-amount" type="number" inputmode="decimal" min="-9999999" max="9999999" value="${c.now}" aria-label="当前可用余额"></div></div>${action('v3-save-balance','用这个金额重新估算','primary full')}${note('之后新增或修改已收录数据，会按差额调整。不是实时银行余额；已留给目标、不打算动用的钱请不计入。')}`);}
function themesView(){return sheetChrome('换一个喜欢的外观',`<div class="skin-grid">${themes.map(t=>`<button class="skin-card ${v3().theme===t.id?'selected':''}" data-skin="${t.id}"><div class="skin-art" style="--skin-bg:${t.colors[0]};--skin-accent:${t.colors[1]};--skin-soft:${t.colors[2]}"><i></i><strong>¥5,089</strong><span></span><b></b></div><div><strong>${t.name}</strong>${v3().theme===t.id?icon('check'):''}</div><small>${t.caption}</small></button>`).join('')}</div>${note('点一下立即应用，不需要再点保存。会记住你的选择。')}`);}
function parseCommitment(input){const text=input.replace(/[，,；;]/g,' ').trim(),monthly=text.match(/每[月期](?:还|应还)?\s*[¥￥]?\s*(\d+(?:\.\d{1,2})?)/),stripped=text.replace(/\d+\s*期/g,'').replace(/\d{1,2}\s*[号日]/g,''),amount=Number(monthly?.[1]||stripped.match(/[¥￥]?\s*(\d+(?:\.\d{1,2})?)/)?.[1]),terms=Number(text.match(/(?:剩余?|还|共|分)?\s*(\d+)\s*期/)?.[1]||1),day=Number(text.match(/(\d{1,2})\s*[号日]/)?.[1]||25);let name=(monthly?text.slice(0,monthly.index):text.split(/\d/)[0]).replace(/[：:\s]+$/,'')||'一笔应还';if(!Number.isFinite(amount)||amount<=0||amount>9999999||terms<1||terms>60||day<1||day>31)return null;return {name:name.slice(0,40),amount:M.round(amount),terms,day};}
function quickDebtView(r){const d=r.id?state().debts.find(d=>d.id===r.id):null,unpaid=d?.schedule.filter(p=>!p.paid),value=r.text??(d?`${d.name} 每月${unpaid?.[0]?.total||d.schedule[0].total} 剩${unpaid?.length||1}期 ${d.day}号`:'');return sheetChrome(d?'调整剩余应还':'加一笔应还',`<p class="sheet-subtitle">说清每月还多少、还几期就行。平台、信用卡、借款，都可以。</p><textarea class="quick-text" id="commitment-text" maxlength="180" placeholder="例如：招商信用卡 每月680 剩6期 25号" aria-label="一句话录入应还">${h(value)}</textarea><div class="text-examples">${action('v3-debt-example','信用卡 · 每月680','pill','data-text="招商信用卡 每月680 剩6期 25号"')}${action('v3-debt-example','其他借款 · 本月300','pill','data-text="一笔借款 300 28号"')}</div><div id="commitment-preview">${commitmentPreview(value)}</div>${action('v3-save-debt','就这样，加入应还','primary full')}${action('v3-paste-debt','从一段还款提醒里选金额','text-button full')}${note('每期金额已经包含平台要求的应还费用；没有账单明细时，不猜本金与利息。默认本月开始，已过还款日会显示为待处理。')}`);}
function commitmentPreview(text){const d=parseCommitment(text);return d?`<div class="quick-result"><span>已理解为</span><strong>${h(d.name)}</strong><p>每月 ${yuan(d.amount)} · 剩 ${d.terms} 期 · 每月 ${d.day} 日</p><small>剩余应还合计 ${yuan(d.amount*d.terms)}</small></div>`:'<div class="quick-empty">输入一句话，金额和期数会在这里直接展示。<br>只知道本月应还？写“借款 300元”就行。</div>';}
debtView=function(r){const d=state().debts.find(d=>d.id===r.id);if(!d)return sheetChrome('应还',note('已经移除'));return sheetChrome(h(d.name),`<div class="detail-hero"><span>剩余待还</span><strong>${yuan(total(d.schedule.filter(p=>!p.paid),p=>p.total))}</strong><small>${d.unknownBreakdown?'按已知应还金额收录，未推断本金与息费':'包含已计算本金与息费'} · 任意来源均可</small></div>${action('v3-edit-debt','一句话调整剩余应还','secondary full',`data-id="${h(d.id)}"`)}${note('点金额调整单期，右侧圆圈直接标记已还。')}${group(d.schedule.map((p,i)=>`<div class="period-row"><button class="period-open" data-action="period" data-id="${h(d.id)}" data-period="${p.id}"><span class="period-num">${i+1}</span><span class="flex-copy"><strong>${p.date}</strong><small>${p.paid?'已经还清这一期':'待还'}${d.unknownBreakdown?'':' · 本金 '+yuan(p.principal)}</small></span><strong>${yuan(p.total)}</strong></button><button class="paid-check ${p.paid?'checked':''}" data-action="paid" data-id="${h(d.id)}" data-period="${p.id}" aria-label="第${i+1}期${p.paid?'撤销已还':'标记已还'}">${p.paid?icon('check'):''}</button></div>`).join(''))}${action('delete-debt','删除这笔应还','danger full',`data-id="${h(d.id)}"`)}`);};
function repaymentsView(){return sheetChrome('接下来要还',state().debts.map(d=>group(row(h(d.name),yuan(total(d.schedule.filter(p=>!p.paid),p=>p.total)),'debt',`data-id="${h(d.id)}"`))).join('')+action('v3-quick-debt','＋ 加一笔应还','primary full')+note('来源可以自己命名；花呗、白条只是示例，不是限定平台。'));}
function coverPicker(d){return `<div class="cover-options">${Object.entries(covers).map(([key,c])=>`<button data-cover="${key}" class="${d.cover===key?'selected':''}" aria-label="选择${c.name}封面"><img src="${c.src}" alt="${c.name}">${d.cover===key?icon('check'):''}</button>`).join('')}${action('v3-upload-cover',icon('plus'),'upload-cover','aria-label="使用自己的照片"')}</div>`;}
function quickWishView(r){const d=r.draft;return sheetChrome(r.kind==='goal'?'建立一个存钱目标':'收藏这个心愿',`<div class="quick-cover">${coverImg(d)}</div>${coverPicker(d)}<input class="inline-name" id="quick-wish-name" value="${h(d.name)}" maxlength="40" placeholder="给它起个名字" aria-label="名称"><div class="price-entry"><label for="quick-wish-price">${r.kind==='goal'?'想存到多少':'大概价格'}</label><div><span>¥</span><input id="quick-wish-price" type="number" inputmode="decimal" min=".01" max="9999999" value="${r.kind==='goal'?d.target:d.price}" aria-label="目标金额或价格"></div></div>${note(r.kind==='goal'?'不用承诺每月存多少。想起来时，存一笔就有进度。':'先收藏就好。真正开始攒钱时，再一键转成目标。')}`,'v3-save-wish');}
function collectionView(){return sheetChrome('让记录少打扰你',`<div class="collection-header"><span>${icon('shield')}</span><h2>以后少记，现在少填。</h2><p>先补历史，新增记录交给安卓端能力。</p></div><div class="collection-option"><span class="step-badge">现在可用</span><h3>一份账单，补齐一段时间</h3><p>选择支付平台导出的账单文件，不用逐张截图。正常记录批量收录，只单独处理疑似重复。</p>${action('v3-file','选择账单文件','primary full')}<small>支持 CSV / Excel 的常见表头；ZIP、密码保护和 PDF 尚不支持。</small></div><div class="collection-option"><span class="step-badge future">安卓端待实现</span><h3>支付后，从通知收录</h3><p>获得通知读取授权后，解析实际收到的提醒。没有金额、没有通知、被隐藏的内容仍可能漏记，需要账单校准。</p>${action('v3-notification-demo','先体验一条通知如何收录','secondary full')}</div>${group(row('我的收支来源',`${v3().sources.length} 个，可自行添加`,'v3-sources','','wallet')+row('粘贴已有账单文字','本机规则识别','v3-message','','book')+row('CSV 是什么？','它是账单表格文件','v3-import-help','','info'))}${note('网页不能读取手机通知，也没有后台连接任何支付账户。截图识别不作为日常主流程。')}`);}
importView=collectionView;
function sourcesView(){return sheetChrome('收支来自哪里',group(v3().sources.map((s,i)=>row(`<span class="source-letter" style="background:${sourceColors[i%sourceColors.length]}">${h(s.name.slice(0,1))}</span>${h(s.name)}`,s.kind==='credit'?'信用 / 借款':'现金收支','v3-source',`data-id="${h(s.id)}"`)).join(''))+action('v3-new-source','＋ 添加其他来源','primary full')+note('这里管理名称与现金 / 信用属性，不代表已经取得平台数据权限。新来源可用标准账单表格或文字录入，平台专用格式仍需适配。'));}
function sourceView(r){const d=r.id?v3().sources.find(s=>s.id===r.id):null;return sheetChrome(d?'收支来源':'添加其他来源',`<input class="inline-name" id="source-name" placeholder="银行、信用卡、平台，叫什么都行" value="${h(d?.name||'')}" maxlength="30" aria-label="来源名称"><div class="inline-fees"><label>资金类型<select id="source-kind"><option value="cash" ${d?.kind!=='credit'?'selected':''}>余额 / 银行卡，付款时钱就减少</option><option value="credit" ${d?.kind==='credit'?'selected':''}>信用 / 借款，还款时才扣现金</option></select></label></div>${!d?`<div class="text-examples">${['云闪付','招商信用卡','美团','其他借款'].map(s=>action('v3-source-example',s,'pill',`data-name="${s}"`)).join('')}</div>`:''}${action('v3-save-source','保存来源','primary full')}${d?action('v3-remove-source','移除此来源','danger full'):''}${note('现金流会根据资金类型处理消费与还款，避免信用消费被扣两次钱。已有记录不会因移除来源被删除。')}`);}
function parseMessage(text,source='其他账户'){const normalized=text.replace(/[，,]/g,' '),income=/工资|薪资|收入|入账|到账/.test(text)&&!/还款/.test(text),refund=/退款|退回/.test(text),repay=/还款|应还/.test(text),match=normalized.match(/(?:人民币|CNY|RMB|[¥￥])\s*(\d+(?:\.\d{1,2})?)/i)||normalized.match(/(?:金额|支付|消费|支出|到账|入账|工资|退款|应还|还款)[^\d]{0,10}(\d+(?:\.\d{1,2})?)/)||normalized.match(/(\d+(?:\.\d{1,2})?)\s*元/);if(!match)return null;const amount=Number(match[1]);if(!(amount>0&&amount<=9999999))return null;const type=refund?'refund':repay?'repayment':income?'income':'expense',detected=v3().sources.find(s=>text.includes(s.name)),account=detected?.name||(source!=='其他账户'?source:text.match(/([\u4e00-\u9fa5A-Za-z]{2,15}(?:银行|信用卡|借条|支付))/)?.[1]||source),name=income?'工资到账':repay?account+'还款':refund?'收到退款':text.match(/(?:商户|商家|消费于)[：:\s]*([^，。\n\s]+)/)?.[1]||'一笔消费';return {id:M.uid(),name,amount,type,actualRepayment:repay&&/还款成功|已还款|还款完成/.test(text),category:'日常',date:M.today(),account,order:'',force:false,selected:true};}
function messageView(r){return sheetChrome(r.demo?'通知收录体验':'粘贴账单文字',`${r.demo?'<div class="demo-explanation">演示流程，不会申请通知权限或读取真实通知。</div>':''}<textarea class="quick-text" id="message-text" maxlength="3000" placeholder="粘贴银行、支付或借款平台的一段消费 / 工资提醒" aria-label="提醒文字">${h(r.text||'')}</textarea><div class="text-examples">${action('v3-message-example','一笔消费','pill','data-text="招商银行 消费人民币68.00元 商户：晚餐"')}${action('v3-message-example','工资到账','pill','data-text="招商银行 工资入账人民币10000.00元"')}</div><div class="inline-fees"><label>来源（识别不出时使用）<select id="message-source"><option>其他账户</option>${v3().sources.map(s=>`<option>${h(s.name)}</option>`).join('')}</select></label></div><div id="message-preview">${messagePreview(r.text||'')}</div>${action('v3-save-message','确认收录这一笔','primary full')}${note('这里是规则识别，无法识别的文字会提示，不会静默猜测。正式安卓端再评估通知解析与现有采集插件适配。')}`);}
function messagePreview(text){const t=parseMessage(text);return t?`<div class="quick-result"><span>识别到 ${t.type==='income'?'收入':t.type==='refund'?'退款':t.type==='repayment'?'还款':'消费'}</span><strong>${yuan(t.amount)}</strong><p>${h(t.name)} · ${h(t.account)}</p></div>`:'<div class="quick-empty">金额、类型和来源会直接显示在这里。</div>';}
const baseReview=reviewView;
reviewView=function(r){const records=r.records,normal=records.filter(t=>!M.duplicate(t)),duplicates=records.filter(t=>M.duplicate(t)),selected=records.filter(t=>t.selected).length;return sheetChrome('收录前，只看例外',`<div class="batch-overview"><span>${icon('check')}</span><strong>${normal.length} 笔可直接收录</strong><p>${duplicates.length} 笔疑似重复，默认跳过</p></div>${r.warning?note(h(r.warning)):''}<details class="optional-settings"><summary>查看全部 ${records.length} 笔 ${icon('down')}</summary><div class="review-list">${records.map((t,i)=>`<div class="review-record"><label class="record-check"><input type="checkbox" data-record="${i}" ${t.selected?'checked':''} aria-label="选择${h(t.name)}"><span>${icon('check')}</span></label><button class="record-edit" data-action="review-record" data-index="${i}"><span class="flex-copy"><strong>${h(t.name)}</strong><small>${t.date} · ${t.type==='income'?'收入':t.type==='refund'?'退款':t.type==='repayment'?'应还计划':'支出'}${M.duplicate(t)?' · 疑似重复':''}</small></span><strong>${yuan(t.amount)}</strong></button></div>`).join('')}</div></details>${duplicates.length?`<div class="exception-note">${icon('info')}疑似重复已跳过；需要保留时，再展开选择并确认。</div>`:''}${action('confirm-import',`一次收录 ${selected} 笔`,'primary full',selected?'':'disabled')}${note(`${h(r.filename||r.source||'演示记录')} · 文件只在这个浏览器解析，不上传。`)}`);};
const baseImportRecord=importRecordView;importRecordView=function(r){return baseImportRecord(r).replace('记录类型</span>', '记录类型</span>').replace('undefined',r.draft.type==='income'?'收入':'支出');};
schema.transaction.type.choices.push(['income','收入'],['transfer','本人账户间转账']);
const baseReadCSV=readCSV;
async function readBillFile(file){if(file.size>5*1024*1024)throw new Error('请选小于 5MB 的账单文件');if(/\.csv$/i.test(file.name))return baseReadCSV(file);if(!/\.xlsx?$/i.test(file.name))throw new Error('目前支持 CSV / Excel；压缩包或加密文件需先解压、解密');if(!window.XLSX)throw new Error('Excel 读取组件尚未加载，请稍后再试');const data=await file.arrayBuffer(),wb=XLSX.read(data,{type:'array',sheetRows:1200,cellFormula:false,cellHTML:false}),sheet=wb.Sheets[wb.SheetNames[0]],csv=XLSX.utils.sheet_to_csv(sheet),bytes=new TextEncoder().encode(csv);return baseReadCSV({name:file.name,size:bytes.byteLength,arrayBuffer:async()=>bytes.buffer});}
function fixedView(){return sheetChrome('固定支出',group(v3().cash.fixed.map(f=>`<div class="plain-row"><span>${h(f.name)} · 每月${f.day}日</span><strong>${yuan(f.amount)} ${action('v3-delete-fixed',icon('x'),'small-icon',`data-id="${h(f.id)}" aria-label="移除固定支出"`)}</strong></div>`).join(''))+`<p class="sheet-subtitle">不是预算，只记录确定要付的房租、订阅等。若当月账本已有同名支出，会避免重复预留。</p><textarea class="quick-text" id="fixed-text" placeholder="例如：房租 2500元 1号" maxlength="150" aria-label="一句话添加固定支出"></textarea>${action('v3-save-fixed','加入固定支出','primary full')}`);}
const baseAbout=aboutView;aboutView=function(){return sheetChrome('TimeWorth · 体验版 03',group(`<div class="info-copy"><h3>围绕月底余钱，减少操作</h3><p>不要求分类预算，不强迫每天记账。工资到账、应还、收录来源和想存的钱，共同形成可解释的月底估算。</p></div><div class="info-copy"><h3>现在可用</h3><p>本机账单 CSV / Excel 读取、文字规则识别、一次批量收录、通用平台应还、工资到账、余额校准、图片心愿、主题皮肤及备份。</p></div><div class="info-copy"><h3>需要安卓端实现和实测</h3><p>通知监听、分享接收、现有自动记账插件适配。网页没有跨 App 通知权限，不会自动读银行或支付账户，截图 OCR、ZIP、密码保护与所有平台格式尚不支持。</p></div>`)+section('调研与组件')+group(`<a class="list-row" href="https://developer.android.com/reference/android/service/notification/NotificationListenerService" target="_blank" rel="noopener"><span class="row-label">Android · 通知监听能力</span>${chevron()}</a><a class="list-row" href="https://github.com/AutoAccountingOrg/AutoAccounting" target="_blank" rel="noopener"><span class="row-label">AutoAccounting · 采集方式参考</span>${chevron()}</a><a class="list-row" href="https://help.copilot.money/en/articles/11157550-quick-start-guide" target="_blank" rel="noopener"><span class="row-label">Copilot Money · 收入与例外核对</span>${chevron()}</a><a class="list-row" href="https://docs.sheetjs.com/docs/solutions/input/" target="_blank" rel="noopener"><span class="row-label">SheetJS CE · 本机 Excel 读取</span>${chevron()}</a>`)+note('界面自行实现；未复制 AutoAccounting 代码，其 GPL-3.0 许可与适配接口仍需正式集成前评估。封面照片来自 Unsplash，随本站静态提供；自选照片只保存在本机。'));};
const baseSheetRender=renderSheet;
renderSheet=function(){const custom={forecast:forecastView,income:incomeView,balance:balanceView,themes:themesView,quickDebt:quickDebtView,repayments:repaymentsView,quickWish:quickWishView,collection:collectionView,sources:sourcesView,source:sourceView,message:messageView,fixed:fixedView,importHelp:()=>sheetChrome('CSV 是什么？',`<div class="info-copy"><h3>它就是一种账单表格文件</h3><p>和 Excel 类似，记录一行行的日期、金额、商户等信息。你不需要编写 CSV，只要在平台导出账单后选择文件。</p><h3>不应该每个月截图几百张</h3><p>完整账单文件用于一次性补历史；之后计划在安卓端接收新的支付通知。通知可能缺失，所以仍需要偶尔校准余额或补账单。</p></div>${action('v3-file','选择一份 CSV 或 Excel','primary full')}${action('download-csv','下载标准样例（其他来源也能用）','text-button full')}`)};if(custom[route.type]){sheet.innerHTML=custom[route.type](route);sheet.hidden=false;backdrop.hidden=false;app.inert=true;$('#tab-bar').inert=true;$('#desktop-nav').inert=true;sheet.scrollTop=0;sheet.focus({preventScroll:true});}else baseSheetRender();};
function rememberWishDraft(){if(route?.type==='quickWish'){route.draft.name=$('#quick-wish-name').value;route.draft[route.kind==='goal'?'target':'price']=Number($('#quick-wish-price').value);}}
function quickWish(kind,id){const item=id?(kind==='goal'?state().goals:state().wishes).find(x=>x.id===id):null;return {type:'quickWish',kind,id,draft:item?M.clone(item):{id:M.uid(),name:'',price:1000,target:5000,cover:kind==='goal'?'mountains':'headphones',icon:kind==='goal'?'mountain':'headphone',entries:[],monthly:0}};}
function saveCommitment(){const d=parseCommitment($('#commitment-text').value);if(!d)throw new Error('写上每月金额即可，例如：借款 每月300 3期');const old=route.id?state().debts.find(x=>x.id===route.id):null,id=old?.id||M.uid(),paid=old?.schedule.filter(p=>p.paid)||[],first=M.month(),newRows=Array.from({length:d.terms},(_,i)=>({id:M.uid(),date:M.dueDate(M.shiftMonth(first,i),d.day),principal:0,interest:0,fee:0,total:d.amount,paid:false})),value={id,name:d.name,principal:d.amount*d.terms,terms:paid.length+d.terms,firstMonth:first,day:d.day,mode:'statement',rate:0,upfront:0,unknownBreakdown:true,schedule:[...paid,...newRows]};if(old)state().debts[state().debts.indexOf(old)]=value;else state().debts.unshift(value);persist();close();render();toast('应还已加入，无需选固定平台');}
function saveQuickWish(){rememberWishDraft();const r=route,d=r.draft,amount=r.kind==='goal'?d.target:d.price;if(!d.name.trim())throw new Error('写一个名称就好');if(!(amount>0&&amount<=9999999))throw new Error('请输入有效金额');d.name=d.name.trim();const list=r.kind==='goal'?state().goals:state().wishes;let index=list.findIndex(x=>x.id===d.id);if(index>=0)list[index]=d;else list.unshift(d);persist();planTab=r.kind==='goal'?'goals':'wishes';navigate('plan');toast('已保存');}
const baseValidateBackup=validateBackup;validateBackup=function(payload){baseValidateBackup(payload);const v=payload.data.v3;if(!v)return;if(!Array.isArray(v.sources)||v.sources.length>100||v.sources.some(s=>typeof s.name!=='string'||s.name.length>30||!['cash','credit'].includes(s.kind)))throw new Error('来源数据无效');if(!v.cash||!Number.isFinite(v.cash.opening)||!Array.isArray(v.cash.incomes)||!Array.isArray(v.cash.fixed)||v.cash.incomes.some(x=>!Number.isFinite(x.amount)||x.amount<0||typeof x.date!=='string')||v.cash.fixed.some(x=>!Number.isFinite(x.amount)||x.amount<0||!Number.isInteger(x.day)||x.day<1||x.day>31||typeof x.name!=='string'))throw new Error('现金流数据无效');};
// New actions never require a preliminary account, budget or multi-page setup.
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
if(b.dataset.skin){v3().theme=b.dataset.skin;state().dark=b.dataset.skin==='night';persist();render();renderSheet();return;}
if(b.dataset.cover){rememberWishDraft();route.draft.cover=b.dataset.cover;route.draft.icon=covers[b.dataset.cover].icon;renderSheet();return;}
const a=b.dataset.action,id=b.dataset.id;
if(a==='v3-themes')open({type:'themes'});else if(a==='v3-forecast')open({type:'forecast'});else if(a==='v3-income')open({type:'income',id,other:!!(id&&!TimeWorthFinance.isSalary(v3().cash.incomes.find(row=>row.id===id)||{}))});else if(a==='v3-other-income')open({type:'income',other:true});else if(a==='v3-save-income'){const amount=numericValue('#income-amount',.01,9999999),date=$('#income-date')?.value||M.today(),opening=Number($('#income-opening')?.value||0);if(!date||!Number.isFinite(opening))throw new Error('请检查日期和期初金额');const iid=route.id||(route.other?M.uid():'salary-'+date.slice(0,7)),row={id:iid,name:route.other?$('#income-name').value.trim()||'其他收入':'工资',amount,date,salary:!route.other,kind:route.other?'other':'salary',received:date<=M.today()},index=v3().cash.incomes.findIndex(x=>x.id===iid);if(index>=0)v3().cash.incomes[index]=row;else v3().cash.incomes.push(row);if($('#income-opening'))v3().cash.opening=M.round(opening);if(!route.other)state().work.salary=amount;persist();close();render();toast(row.received?'到账已收录，月底预测已更新':'已作为未来收入纳入估算');}
else if(a==='v3-balance')open({type:'balance'});else if(a==='v3-save-balance'){const amount=numericValue('#balance-amount',-9999999,9999999),c=cashSummary();v3().cash.anchor={month:M.month(),amount,baseline:c.derived,date:M.today()};persist();close();render();toast('已从这个余额继续估算');}
else if(a==='v3-basis'){state().work.basis=state().work.basis==='real'?'work':'real';persist();refreshAll();}
else if(a==='v3-repayments')open({type:'repayments'});else if(a==='v3-quick-debt')open({type:'quickDebt'});else if(a==='v3-edit-debt')open({type:'quickDebt',id});else if(a==='v3-debt-example'){$('#commitment-text').value=b.dataset.text;$('#commitment-preview').innerHTML=commitmentPreview(b.dataset.text);}else if(a==='v3-save-debt')saveCommitment();else if(a==='v3-paste-debt')open({type:'message'});
else if(a==='v3-new-wish'||a==='v3-new-goal')open(quickWish(a==='v3-new-goal'?'goal':'wish'));else if(a==='v3-edit-wish')open(quickWish('wish',id));else if(a==='v3-edit-goal')open(quickWish('goal',id));else if(a==='v3-save-wish')saveQuickWish();else if(a==='v3-start-saving'){const w=state().wishes.find(x=>x.id===id),existing=state().goals.find(g=>g.fromWish===id);if(existing){open({type:'goal',id:existing.id});return;}const g={id:M.uid(),name:w.name,target:w.price,cover:w.cover,icon:w.icon,badgeType:w.badgeType,badge:w.badge,badgeTint:w.badgeTint,monthly:0,entries:[],fromWish:id};state().goals.unshift(g);persist();planTab='goals';navigate('plan');toast('开始攒了，随时存一笔就有进度');}
else if(a==='v3-upload-cover'){rememberWishDraft();chooseFile('image/jpeg,image/png,image/webp',async file=>{if(file.size>600*1024)throw new Error('请选小于 600KB 的照片，避免占满本机存储');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('支持 JPG、PNG、WebP');const reader=new FileReader();reader.onload=()=>{route.draft.cover=reader.result;renderSheet();};reader.readAsDataURL(file);});}
else if(a==='v3-save-calculation'||a==='v3-save-calc-wish'){if(!validateCalculator())return;const d=route.draft;d.name=$('#quick-product').value.trim()||'一个想买的东西';if(d.terms>1&&a==='v3-save-calculation'){const debt=M.makeDebt({id:M.uid(),name:d.name,principal:d.price,terms:d.terms,mode:d.mode,rate:d.rate,upfront:d.upfront,day:d.day,firstMonth:d.firstMonth});state().debts.unshift(debt);persist();close();render();toast('已直接加入应还');}else{state().wishes.unshift({id:M.uid(),name:d.name,price:d.price,icon:'bag',cover:'headphones',note:''});persist();planTab='wishes';navigate('plan');toast('已收藏');}}
else if(a==='v3-collection')open({type:'collection'});else if(a==='v3-file')chooseFile('.csv,.xlsx,.xls',readBillFile);else if(a==='v3-import-help')open({type:'importHelp'});else if(a==='v3-sources')open({type:'sources'});else if(a==='v3-source')open({type:'source',id});else if(a==='v3-new-source')open({type:'source'});else if(a==='v3-source-example'){$('#source-name').value=b.dataset.name;$('#source-kind').value=/信用|借款/.test(b.dataset.name)?'credit':'cash';}
else if(a==='v3-save-source'){const name=$('#source-name').value.trim(),kind=$('#source-kind').value;if(!name)throw new Error('写一个来源名称就好');if(v3().sources.some(s=>s.name===name&&s.id!==route.id))throw new Error('已经有这个来源');if(route.id)Object.assign(v3().sources.find(s=>s.id===route.id),{name,kind});else v3().sources.push({id:M.uid(),name,kind});persist();back();render();toast('来源已保存');}else if(a==='v3-remove-source'){v3().sources=v3().sources.filter(s=>s.id!==route.id);persist();back();render();}
else if(a==='v3-message'||a==='v3-notification-demo')open({type:'message',demo:a==='v3-notification-demo',text:a==='v3-notification-demo'?'招商银行 消费人民币68.00元 商户：晚餐':''});else if(a==='v3-message-example'){$('#message-text').value=b.dataset.text;$('#message-preview').innerHTML=messagePreview(b.dataset.text);}else if(a==='v3-save-message'){const t=parseMessage($('#message-text').value,$('#message-source').value);if(!t)throw new Error('没有明确识别到金额，请补充“金额xx元”后核对');t.key=M.fingerprint(t);t.selected=!M.duplicate(t);open({type:'review',source:t.account,filename:route.demo?'演示通知（未读取系统通知）':'粘贴的文字',records:[t]});}
else if(a==='v3-fixed')open({type:'fixed'});else if(a==='v3-save-fixed'){const d=parseCommitment($('#fixed-text').value);if(!d)throw new Error('例如写：房租 2500元 1号');v3().cash.fixed.push({id:M.uid(),name:d.name,amount:d.amount,day:d.day});persist();refreshAll();toast('已加入，已有同名支出不会重复预留');}else if(a==='v3-delete-fixed'){v3().cash.fixed=v3().cash.fixed.filter(x=>x.id!==id);persist();refreshAll();}
}catch(err){toast(err.message||'请检查输入');}});
document.addEventListener('input',e=>{if(e.target.id==='commitment-text')$('#commitment-preview').innerHTML=commitmentPreview(e.target.value);if(e.target.id==='message-text')$('#message-preview').innerHTML=messagePreview(e.target.value);if(e.target.id==='quick-product'&&route?.type==='calculator')route.draft.name=e.target.value;});
document.addEventListener('change',e=>{if(route?.type!=='calculator'||!e.target.id.startsWith('quick-fee-'))return;try{if(!validateCalculator())return;route.draft.name=$('#quick-product').value;const key=e.target.id.slice(10),map={mode:'mode',rate:'rate',upfront:'upfront',terms:'terms',day:'day'};let val=key==='mode'?e.target.value:Number(e.target.value);if(key!=='mode'&&(!Number.isFinite(val)||val<0||(key==='rate'&&val>100)||(key==='terms'&&(!Number.isInteger(val)||val<2||val>60))||(key==='day'&&(!Number.isInteger(val)||val<1||val>31))||(key==='upfront'&&val>999999)))throw new Error('请检查费率、期数或还款日');route.draft[map[key]]=val;const scroll=sheet.scrollTop;renderSheet();sheet.scrollTop=scroll;}catch(err){toast(err.message);}});
window.__timeworthPreview.cashSummary=cashSummary;window.__timeworthPreview.parseCommitment=parseCommitment;window.__timeworthPreview.parseMessage=parseMessage;window.__timeworthPreview.reset=()=>{M.reset();planTab='wishes';navigate('home');};
render(false);
const oldPeriodView=periodView;periodView=function(r){const debt=state().debts.find(d=>d.id===r.debtId);if(!debt?.unknownBreakdown)return oldPeriodView(r);return sheetChrome('这一期要还多少',`<div class="price-entry"><label for="period-total">已知应还金额（包含息费）</label><div><span>¥</span><input type="number" id="period-total" inputmode="decimal" min=".01" max="9999999" value="${r.draft.total}" aria-label="本期应还金额"></div></div><details class="optional-settings"><summary>调整日期 ${icon('down')}</summary><div class="compact-input"><label for="period-date">还款日期</label><input type="date" id="period-date" value="${r.draft.date}"></div></details>${note('不知道本金与利息怎么拆，也不影响先把应还安排好。')}`,'v3-save-period');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.action!=='v3-save-period')return;try{const value=numericValue('#period-total',.01,9999999),d=state().debts.find(d=>d.id===route.debtId),p=d.schedule.find(p=>p.id===route.periodId);p.total=value;p.date=$('#period-date').value||p.date;persist();returnParent();render();toast('本期应还已更新');}catch(err){toast(err.message);}});
const importBeforeV3=importSelected;importSelected=function(r){const actual=r.records.filter(t=>t.selected&&t.actualRepayment);if(!actual.length)return importBeforeV3(r);if(r.records.some(t=>t.selected&&M.duplicate(t)&&!t.force))return importBeforeV3(r);for(const t of actual){let d=findDebtForImport(t),p=d?.schedule.find(p=>p.date.startsWith(t.date.slice(0,7))&&!p.paid);if(p&&Math.abs(p.total-t.amount)<.005){p.paid=true;p.paidDate=t.date;}else{d={id:M.uid(),name:t.account+'已还款',principal:t.amount,terms:1,mode:'statement',rate:0,upfront:0,firstMonth:t.date.slice(0,7),day:Number(t.date.slice(8)),unknownBreakdown:true,schedule:[{id:M.uid(),date:t.date,paidDate:t.date,total:t.amount,principal:0,interest:0,fee:0,paid:true}]};state().debts.push(d);}state().imports.push(t.key);}r.records=r.records.filter(t=>!actual.includes(t));if(r.records.some(t=>t.selected))importBeforeV3(r);else{persist();navigate('ledger');toast('已收录实际还款，未重复记为消费');}};
window.__timeworthPreview.validateBackup=validateBackup;
